import cv2,numpy as np
A=np.load('.tmp/high.npy',mmap_mode='r');b=np.median(A[:29],axis=0).astype(np.uint8); R,G,B=np.moveaxis(b.astype(float),2,0)
for desc, mask in [('blue',(B>R*1.2)&(G>R*1.15)),('red',(R>G*1.2)&(R>B*1.1)),('small',(R>200)&(abs(R-G)<10)&(abs(G-B)<10))]:
